function main() {
    var lastMessage = project.getMessages({
        contact_id: contact.id,
        direction: 'incoming',
        sort_dir: 'desc'
    }).limit(1).next();

    if (lastMessage) {
        var daysSince = (Date.now() - lastMessage.time_created * 1000) / 86400000;
        if (daysSince > 30) {
            contact.addToGroup(project.getOrCreateGroup({name: 'Inactive'}));
        }
    }
}

